from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    results = []
    groups = paren_string.split()
    for group in groups:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':  
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1
        results.append(max_depth)
    return results

from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    sum_result = sum(numbers)
    product_result = 1
    for number in numbers:
        product_result *= number
    return (sum_result, product_result)

from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    counts = {}
    for number in numbers:
        counts[number] = counts.get(number, 0) + 1
    return [number for number in numbers if counts[number] == 1]

def fizz_buzz(n: int):
    """Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13."""
    count = 0
    seen = set()
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            s = str(i)
            if '7' in s and i not in seen:
                count += s.count('7')
                seen.add(i)
    return count

def median(l: list):
    """Return median of elements in the list l."""
    l_sorted = sorted(l)
    n = len(l_sorted)
    mid = n // 2
    if n % 2 == 1:
        return l_sorted[mid]
    else:
        return (l_sorted[mid - 1] + l_sorted[mid]) / 2.0

def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""
    largest = 1
    # Check for number of 2s that divide n
    while n % 2 == 0:
        largest = 2
        n //= 2
    # n must be odd at this point, thus a skip of 2 (i.e., i = i + 2) can be used
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            largest = i
            n //= i
    # This condition is to check if n is a prime number greater than 2
    if n > 2:
        largest = n
    return largest

def correct_bracketing(brackets: str):
    balance = 0
    for char in brackets:
        if char == '(':  
            balance += 1
        elif char == ')':  
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def total_match(lst1, lst2):
    total_chars_lst1 = sum(len(s) for s in lst1)
    total_chars_lst2 = sum(len(s) for s in lst2)
    if total_chars_lst1 <= total_chars_lst2:
        return lst1
    return lst2

def next_smallest(lst):
    unique_elements = sorted(set(lst))
    return unique_elements[1] if len(unique_elements) > 1 else None

